(() => {
    'use strict';

    const OPTIONS = [['cn', '🇨🇳 国区', '🇨🇳 CN'], ['hk', '🇭🇰 港区', '🇭🇰 HK'],
        ['jp', '🇯🇵 日区', '🇯🇵 JP'], ['us', '🇺🇸 美区', '🇺🇸 US'],
        ['off', '🌐 默认', '🌐 Default']];
    const SETTING = 'steam-store-region';
    const COLLAPSED_SETTING = 'steam-store-region-collapsed';
    const LOOP_KEY = 'cycledm-steam-region-last-navigation';
    // Generated by src/build-styles.py from Tailwind CSS 3.4.17 (MIT).
    // tailwind:start
    const STYLES = ":host{all:initial}.visible{visibility:visible}.fixed{position:fixed}.bottom-4{bottom:1rem}.right-4{right:1rem}.m-0{margin:0}.box-border{box-sizing:border-box}.flex{display:flex}.inline-flex{display:inline-flex}.grid{display:grid}.h-10{height:2.5rem}.min-h-0{min-height:0}.w-10{width:2.5rem}.w-max{width:-moz-max-content;width:max-content}.min-w-0{min-width:0}.shrink-0{flex-shrink:0}.cursor-pointer{cursor:pointer}.flex-wrap{flex-wrap:wrap}.items-center{align-items:center}.justify-center{justify-content:center}.gap-1{gap:.25rem}.overflow-hidden{overflow:hidden}.rounded-lg{border-radius:.5rem}.rounded-xl{border-radius:.75rem}.border{border-width:1px}.border-0{border-width:0}.border-solid{border-style:solid}.border-slate-600{--tw-border-opacity:1;border-color:rgb(71 85 105/var(--tw-border-opacity,1))}.bg-slate-700{--tw-bg-opacity:1;background-color:rgb(51 65 85/var(--tw-bg-opacity,1))}.bg-slate-900{--tw-bg-opacity:1;background-color:rgb(15 23 42/var(--tw-bg-opacity,1))}.p-0{padding:0}.p-1{padding:.25rem}.p-2{padding:.5rem}.px-2{padding-left:.5rem;padding-right:.5rem}.px-3{padding-left:.75rem;padding-right:.75rem}.py-2{padding-top:.5rem;padding-bottom:.5rem}.font-sans{font-family:ui-sans-serif,system-ui,sans-serif,Apple Color Emoji,Segoe UI Emoji,Segoe UI Symbol,Noto Color Emoji}.text-sm{font-size:.875rem;line-height:1.25rem}.text-xs{font-size:.75rem;line-height:1rem}.font-medium{font-weight:500}.leading-5{line-height:1.25rem}.leading-none{line-height:1}.text-slate-100{--tw-text-opacity:1;color:rgb(241 245 249/var(--tw-text-opacity,1))}.text-slate-300{--tw-text-opacity:1;color:rgb(203 213 225/var(--tw-text-opacity,1))}.text-white{--tw-text-opacity:1;color:rgb(255 255 255/var(--tw-text-opacity,1))}.opacity-100{opacity:1}.shadow{--tw-shadow:0 1px 3px 0 rgba(0,0,0,.1),0 1px 2px -1px rgba(0,0,0,.1);--tw-shadow-colored:0 1px 3px 0 var(--tw-shadow-color),0 1px 2px -1px var(--tw-shadow-color)}.shadow,.shadow-lg{box-shadow:var(--tw-ring-offset-shadow,0 0 #0000),var(--tw-ring-shadow,0 0 #0000),var(--tw-shadow)}.shadow-lg{--tw-shadow:0 10px 15px -3px rgba(0,0,0,.1),0 4px 6px -4px rgba(0,0,0,.1);--tw-shadow-colored:0 10px 15px -3px var(--tw-shadow-color),0 4px 6px -4px var(--tw-shadow-color)}.filter{filter:var(--tw-blur) var(--tw-brightness) var(--tw-contrast) var(--tw-grayscale) var(--tw-hue-rotate) var(--tw-invert) var(--tw-saturate) var(--tw-sepia) var(--tw-drop-shadow)}.duration-200{transition-duration:.2s}.ease-in-out{transition-timing-function:cubic-bezier(.4,0,.2,1)}.region-panel{z-index:2147483647;display:flex;flex-direction:column;align-items:flex-end;gap:.5rem;border-radius:.75rem;border:1px solid rgba(100,116,139,.6);background-color:rgba(15,23,42,.95);padding:.5rem;font-family:ui-sans-serif,system-ui,sans-serif,Apple Color Emoji,Segoe UI Emoji,Segoe UI Symbol,Noto Color Emoji;font-size:.875rem;line-height:1.25rem;--tw-text-opacity:1;color:rgb(255 255 255/var(--tw-text-opacity,1));--tw-shadow:0 10px 15px -3px rgba(0,0,0,.1),0 4px 6px -4px rgba(0,0,0,.1);--tw-shadow-colored:0 10px 15px -3px var(--tw-shadow-color),0 4px 6px -4px var(--tw-shadow-color);box-shadow:var(--tw-ring-offset-shadow,0 0 #0000),var(--tw-ring-shadow,0 0 #0000),var(--tw-shadow);bottom:calc(1rem + env(safe-area-inset-bottom, 0px));right:calc(1rem + env(safe-area-inset-right, 0px));max-width:calc(100vw - 2rem - env(safe-area-inset-left, 0px) - env(safe-area-inset-right, 0px));transition:gap .2s ease-in-out}.region-panel[data-collapsed=true]{gap:0}.region-collapsible{display:grid;min-height:0;min-width:0;grid-template-columns:1fr;grid-template-rows:1fr;opacity:1;max-width:40rem;max-height:100vh;transition:grid-template-columns .2s ease-in-out,grid-template-rows .2s ease-in-out,max-width .2s ease-in-out,max-height .2s ease-in-out,opacity .2s ease-in-out}.region-collapsible[data-collapsed=true]{grid-template-columns:0fr;grid-template-rows:0fr;max-width:0;max-height:0;opacity:0}.region-controls{display:flex;width:-moz-max-content;width:max-content;min-width:8.5rem;flex-direction:column;align-items:stretch;gap:.25rem;overflow-y:auto;overscroll-behavior:contain;padding:.25rem;max-width:calc(100vw - 4rem - env(safe-area-inset-left, 0px) - env(safe-area-inset-right, 0px));max-height:calc(100vh - 8rem - env(safe-area-inset-top, 0px) - env(safe-area-inset-bottom, 0px));max-height:calc(100dvh - 8rem - env(safe-area-inset-top, 0px) - env(safe-area-inset-bottom, 0px))}.region-status{padding:.25rem .5rem;font-size:.75rem;line-height:1rem;--tw-text-opacity:1;color:rgb(226 232 240/var(--tw-text-opacity,1))}.region-button,.region-toggle{margin:0;box-sizing:border-box;display:inline-flex;min-height:44px;flex-shrink:0;cursor:pointer;align-items:center;justify-content:center;border-radius:.5rem;border-width:0;border-style:solid;background-color:rgba(51,65,85,.8);font-family:ui-sans-serif,system-ui,sans-serif,Apple Color Emoji,Segoe UI Emoji,Segoe UI Symbol,Noto Color Emoji;font-size:.875rem;line-height:1.25rem;--tw-text-opacity:1;color:rgb(255 255 255/var(--tw-text-opacity,1));-webkit-tap-highlight-color:transparent;touch-action:manipulation}.region-button{padding:.5rem .75rem;font-weight:500}.region-toggle{height:44px;width:44px;padding:0;line-height:1}.region-toggle[data-collapsed=true]{font-size:24px}.region-button:hover,.region-toggle:hover{background-color:rgba(71,85,105,.9)}.region-button[aria-pressed=true]{--tw-bg-opacity:1;background-color:rgb(3 105 161/var(--tw-bg-opacity,1))}.region-button:disabled{cursor:default;opacity:.6}.region-button:focus-visible,.region-toggle:focus-visible{outline-style:solid;outline-width:2px;outline-offset:2px;outline-color:#7dd3fc}@media (min-width:640px){.region-panel{flex-direction:row;align-items:center;gap:.25rem}.region-panel[data-collapsed=true]{gap:0}.region-controls{flex-direction:row;flex-wrap:wrap;align-items:center;max-width:calc(100vw - 7rem - env(safe-area-inset-left, 0px) - env(safe-area-inset-right, 0px))}}@supports ((-webkit-backdrop-filter:blur(16px)) or (backdrop-filter:blur(16px))){.region-panel{background-color:rgba(15,23,42,.8);-webkit-backdrop-filter:blur(16px);backdrop-filter:blur(16px)}}@media (prefers-reduced-motion:reduce){.region-collapsible,.region-panel{transition:none}}@media (prefers-reduced-transparency:reduce){.region-panel{--tw-bg-opacity:1;background-color:rgb(15 23 42/var(--tw-bg-opacity,1));-webkit-backdrop-filter:none;backdrop-filter:none}}";
    // tailwind:end

    if (window.top !== window.self || location.origin !== 'https://store.steampowered.com') return;
    const allowed = /^\/(?:$|(?:app|bundle|sub|search|category|genre|tags|specials|sale|charts|publisher|developer|franchise|curators?|wishlist|points|explore|steamdeck)(?:\/|$))/;
    if (!allowed.test(location.pathname) || /^\/search\/results(?:\/|$)/i.test(location.pathname)) return;

    const chinese = /^zh\b/i.test(document.documentElement.lang || navigator.language);
    let region = 'cn';
    try {
        const saved = GM_getValue(SETTING, 'cn');
        if (OPTIONS.some(([value]) => value === saved)) region = saved;
    } catch (_) { /* Retain the default when settings cannot be read. */ }

    function loginState() {
        // Account UI takes priority over a possibly stale signed-out marker.
        if (document.querySelector('#account_pulldown, #account_dropdown, #global_actions .user_avatar')) return 'member';
        const info = document.querySelector('[data-userinfo]');
        if (info) {
            try {
                const user = JSON.parse(info.getAttribute('data-userinfo'));
                if (user.logged_in === true) return 'member';
                if (user.logged_in === false) return 'guest';
            } catch (_) { /* Fall back to the global header. */ }
        }
        const links = document.querySelectorAll('#global_actions a[href]');
        for (const link of links) {
            try {
                const url = new URL(link.href, location.href);
                if (url.origin === location.origin && /^\/login(?:\/|$)/.test(url.pathname)) return 'guest';
            } catch (_) { /* Ignore malformed links. */ }
        }
        return 'unknown';
    }

    function regionURL(force) {
        // Preserve the original spelling/order of unrelated parameters and the hash.
        const raw = location.href;
        const hashAt = raw.indexOf('#');
        const base = hashAt < 0 ? raw : raw.slice(0, hashAt);
        const hash = hashAt < 0 ? '' : raw.slice(hashAt);
        const queryAt = base.indexOf('?');
        const parts = queryAt < 0 ? [] : base.slice(queryAt + 1).split('&');
        const isCC = part => decodeURIComponent(part.split('=')[0].replace(/\+/g, ' ')).toLowerCase() === 'cc';
        if (!force && parts.some(isCC)) return null;
        if (region === 'off' && !parts.some(isCC)) return null;
        const kept = force ? parts.filter(part => !isCC(part)) : parts;
        const prefix = queryAt < 0 ? base : base.slice(0, queryAt);
        const query = kept.join('&');
        if (region === 'off') return prefix + (query ? '?' + query : '') + hash;
        return prefix + '?' + query + (query && !query.endsWith('&') ? '&' : '') + 'cc=' + region + hash;
    }

    function navigate(force = false) {
        if (region === 'off' && !force) return;
        if (region !== 'off' && loginState() !== 'guest') return;
        try {
            const target = regionURL(force);
            if (!target || target === location.href) return;
            // If Steam strips cc, avoid repeatedly reloading the same destination.
            // Without session storage, skip automatic navigation conservatively.
            if (!force) {
                const previous = JSON.parse(sessionStorage.getItem(LOOP_KEY) || 'null');
                if (previous && previous.url === target && Date.now() - previous.time < 15000) return;
                sessionStorage.setItem(LOOP_KEY, JSON.stringify({ url: target, time: Date.now() }));
            }
            location.replace(target);
        } catch (_) { /* Malformed URLs or unavailable storage: leave the page alone. */ }
    }

    function mount() {
        if (!document.body || document.getElementById('cycledm-steam-store-region')) return;
        const host = document.createElement('div');
        host.id = 'cycledm-steam-store-region';
        const shadow = host.attachShadow({ mode: 'open' });
        const style = document.createElement('style');
        style.textContent = STYLES;
        const panel = document.createElement('nav');
        panel.className = 'fixed region-panel';
        panel.setAttribute('aria-label', chinese ? 'Steam 商店区域' : 'Steam store region');
        let collapsed = true;
        try {
            const saved = GM_getValue(COLLAPSED_SETTING, true);
            if (typeof saved === 'boolean') collapsed = saved;
        } catch (_) { /* Start collapsed if the saved state cannot be read. */ }
        const collapsible = document.createElement('div');
        collapsible.id = 'region-controls';
        collapsible.className = 'region-collapsible';
        const clip = document.createElement('div');
        clip.className = 'min-h-0 min-w-0 overflow-hidden';
        const controls = document.createElement('div');
        controls.className = 'region-controls';
        clip.append(controls);
        collapsible.append(clip);
        const toggle = document.createElement('button');
        toggle.type = 'button';
        toggle.className = 'region-toggle';
        toggle.setAttribute('aria-controls', collapsible.id);
        function renderCollapsed() {
            panel.setAttribute('data-collapsed', String(collapsed));
            toggle.setAttribute('data-collapsed', String(collapsed));
            collapsible.setAttribute('data-collapsed', String(collapsed));
            collapsible.setAttribute('aria-hidden', String(collapsed));
            collapsible.inert = collapsed;
            toggle.setAttribute('aria-expanded', String(!collapsed));
            toggle.textContent = collapsed
                ? OPTIONS.find(([value]) => value === region)[1].split(' ')[0] : '⌄';
            toggle.title = collapsed ? (chinese ? '展开区域工具栏' : 'Expand region toolbar')
                : (chinese ? '折叠区域工具栏' : 'Collapse region toolbar');
            toggle.setAttribute('aria-label', toggle.title);
        }
        renderCollapsed();
        const status = document.createElement('span');
        status.className = 'region-status';
        status.setAttribute('role', 'status');
        const buttons = [];
        function refresh() {
            const state = loginState();
            status.textContent = state === 'member' ? (chinese ? '已登录 · 暂停' : 'Signed in · paused')
                : state === 'unknown' ? (chinese ? '登录状态未知 · 暂停' : 'Unknown login · paused')
                    : (chinese ? '商店区域' : 'Store region');
            for (const [button, value] of buttons) {
                button.setAttribute('aria-pressed', String(value === region));
                button.disabled = value !== 'off' && state !== 'guest';
            }
        }
        controls.append(status);
        for (const [value, zh, en] of OPTIONS) {
            const button = document.createElement('button');
            button.type = 'button';
            button.textContent = chinese ? zh : en;
            button.className = 'region-button';
            button.title = value === 'off'
                ? (chinese ? '移除当前网址的 cc 参数并停止后续改写' : 'Remove cc from this URL and stop future rewrites')
                : (chinese ? '保存区域并重新加载当前页面' : 'Save region and reload this page');
            button.addEventListener('click', () => {
                if (value !== 'off' && loginState() !== 'guest') { refresh(); return; }
                try { GM_setValue(SETTING, value); }
                catch (_) {
                    status.textContent = chinese ? '无法保存设置' : 'Could not save preference';
                    return;
                }
                region = value;
                renderCollapsed();
                refresh();
                navigate(true);
            });
            buttons.push([button, value]);
            controls.append(button);
        }
        toggle.addEventListener('click', () => {
            try { GM_setValue(COLLAPSED_SETTING, !collapsed); }
            catch (_) {
                toggle.title = chinese ? '无法保存折叠状态' : 'Could not save collapsed state';
                toggle.setAttribute('aria-label', toggle.title);
                return;
            }
            collapsed = !collapsed;
            renderCollapsed();
        });
        panel.append(collapsible, toggle);
        refresh();
        shadow.append(style, panel);
        document.body.append(host);
        window.addEventListener('pageshow', () => { refresh(); navigate(); });
        document.addEventListener('visibilitychange', () => {
            if (document.visibilityState === 'visible') refresh();
        });
    }

    mount();
    navigate();
})();
